// COMPONENT: a UI unit (class + template + styles).
@Component({
  selector: 'app-hero',
  template: `<h2>{{hero.name}}</h2>`,
})
export class HeroComponent {
  hero = { name: 'Spider-Man' };
}

// MODULE: an organizer that DECLARES components and PROVIDES services.
@NgModule({
  declarations: [HeroComponent, AppComponent],  // components belong here
  imports: [BrowserModule],                        // other modules used
  providers: [{ provide: HeroService }],           // services for DI
  bootstrap: [AppComponent],                        // root component
})
export class AppModule {}
//   The module doesn't render; the components it declares do.
